export type ParsedBuyPullInstruction<
  TProgram extends string = typeof TEQUILA_GACHA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    player: TAccountMetas[0];
    machine: TAccountMetas[1];
    playerState: TAccountMetas[2];
    pull: TAccountMetas[3];
    seller: TAccountMetas[4];
    systemProgram: TAccountMetas[5];
    playerUsdc?: TAccountMetas[6] | undefined;
    sellerUsdc?: TAccountMetas[7] | undefined;
    usdcMint?: TAccountMetas[8] | undefined;
    tokenProgram?: TAccountMetas[9] | undefined;
  };
  data: BuyPullInstructionData;
};

export function parseBuyPullInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBuyPullInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === TEQUILA_GACHA_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      player: getNextAccount(),
      machine: getNextAccount(),
      playerState: getNextAccount(),
      pull: getNextAccount(),
      seller: getNextAccount(),
      systemProgram: getNextAccount(),
      playerUsdc: getNextOptionalAccount(),
      sellerUsdc: getNextOptionalAccount(),
      usdcMint: getNextOptionalAccount(),
      tokenProgram: getNextOptionalAccount(),
    },
    data: getBuyPullInstructionDataDecoder().decode(instruction.data),
  };
}
